let input;
try {
  input = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  // AI passed raw string - use it as pattern, get context from workflow
  const ctx = $('Merge Files')?.item?.json || {};
  input = { pattern: query, owner: ctx.owner || ctx.site?.owner, repo: ctx.repo || ctx.site?.repo };
}
const { pattern, owner, repo, fileTypes } = input;
if (!owner || !repo) return 'Error: Missing owner or repo. Pass JSON: {"pattern": "...", "owner": "...", "repo": "..."}';

let extFilter = '';
if (Array.isArray(fileTypes) && fileTypes.length > 0) {
  extFilter = ` extension:${fileTypes.join(',')}`;
} else if (typeof fileTypes === 'string' && fileTypes.trim().length > 0) {
  extFilter = ` extension:${fileTypes}`;
}

const q = `${pattern} repo:${owner}/${repo}${extFilter}`;

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/search/code?q=${encodeURIComponent(q)}&per_page=10`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    }
  });
  if (!response.items) return JSON.stringify({ error: response.message || 'No results' });
  return JSON.stringify(response.items.map(i => ({ path: i.path, score: i.score })));
} catch (e) {
  return `Error: ${e.message}`;
}

let input;
try {
  input = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  // AI passed raw string - use it as filePath, get context from workflow
  const ctx = $('Merge Files')?.item?.json || {};
  input = { filePath: query, owner: ctx.owner || ctx.site?.owner, repo: ctx.repo || ctx.site?.repo, branch: ctx.branch || ctx.site?.default_branch || 'main' };
}
const { filePath, owner, repo, branch = 'main' } = input;
if (!owner || !repo) return 'Error: Missing owner or repo. Pass JSON: {"filePath": "...", "owner": "...", "repo": "..."}';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${filePath}?ref=${branch}`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    }
  });

  if (response.content && response.encoding === 'base64') {
    return Buffer.from(response.content, 'base64').toString('utf8');
  }
  return 'Error: File not found or not readable';
} catch (e) {
  return `Error: ${e.message} (File: ${filePath})`;
}

let input;
try {
  input = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  // AI passed raw string - use it as pattern, get context from workflow
  const ctx = $('Merge Files')?.item?.json || {};
  input = { pattern: query, owner: ctx.owner || ctx.site?.owner, repo: ctx.repo || ctx.site?.repo, branch: ctx.branch || ctx.site?.default_branch || 'main' };
}
const { pattern, owner, repo, branch = 'main' } = input;
if (!owner || !repo) return 'Error: Missing owner or repo. Pass JSON: {"pattern": "...", "owner": "...", "repo": "..."}';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: {
      'Authorization': 'Bearer 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',
      'Accept': 'application/vnd.github+json'
    }
  });

  if (!response.tree) return 'Error: Could not fetch tree';

  let files;
  if(pattern === '**/*' || pattern === '**') {
     files = response.tree.filter(f => f.type === 'blob').map(f => f.path);
  } else {
     const regex = new RegExp('^' + pattern.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*') + '$');
     files = response.tree.filter(f => f.type === 'blob' && regex.test(f.path)).map(f => f.path);
  }

  return JSON.stringify(files.slice(0, 50));
} catch (e) {
  return `Error: ${e.message}`;
}

const ctx = $('Merge Files').item.json;
const raw = $('AI Plan').item.json;

let plan;
let out = String(raw?.output ?? raw?.text ?? '');

try {
  if (raw?.output && typeof raw.output === 'object') {
    plan = raw.output;
  } else {
    const jsonMatch = out.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      let jsonStr = jsonMatch[0]
        .replace(/[\x00-\x1F\x7F]/g, ' ')
        .replace(/,\s*}/g, '}')
        .replace(/,\s*]/g, ']');
      try {
        plan = JSON.parse(jsonStr);
      } catch (e1) {
        plan = {
          intent: 'modify',
          humanSummary: out.slice(0, 500) || 'AI response was malformed',
          unifiedDiff: '',
          fileTargets: [],
          warnings: ['AI response was malformed - please try again']
        };
      }
    } else {
      plan = {
        intent: 'unknown',
        humanSummary: out.slice(0, 500) || 'AI did not provide structured output',
        unifiedDiff: '',
        fileTargets: [],
        warnings: ['Could not parse AI response - raw output saved']
      };
    }
  }
} catch (e) {
  plan = {
    intent: 'error',
    humanSummary: 'Error parsing AI response: ' + e.message,
    unifiedDiff: '',
    fileTargets: [],
    warnings: ['Parse error: ' + e.message, 'Raw output: ' + out.slice(0, 200)]
  };
}

plan.warnings = Array.isArray(plan.warnings) ? plan.warnings : [];
plan.unifiedDiff = typeof plan.unifiedDiff === 'string' ? plan.unifiedDiff : '';
plan.humanSummary = plan.humanSummary || '';
plan.fileTargets = Array.isArray(plan.fileTargets) ? plan.fileTargets : [];
plan.intent = plan.intent || 'modify';

return [{ json: { ...ctx, plan } }];

const ctx = $input.first().json;
if (!ctx?.site) throw new Error('Missing site');
if (!ctx?.plan) throw new Error('Missing plan');

const allowed = ctx.site.allowedPaths || ['src/**'];
const forbidden = [/\.env/i, /secret/i, /node_modules/i, /\.git/i];

function globMatch(p, pats) {
  return pats.some(g => {
    const re = new RegExp('^' + g.replace(/\*\*/g, '.*').replace(/\*/g, '[^/]*'));
    return re.test(p);
  });
}

const badPath = [];
(ctx.plan.fileTargets || []).forEach(t => {
  if (!globMatch(t.path, allowed)) badPath.push(t.path);
  if (forbidden.some(f => f.test(t.path))) badPath.push(t.path);
});

if (badPath.length) {
  ctx.plan.warnings.push('Some paths not allowed: ' + [...new Set(badPath)].join(', '));
}

return [{ json: ctx }];

const ctx = $('Guardrails').item.json;
const applyResp = $input.first().json;

// Handle apply response
const filesChanged = applyResp.filesChanged || [];
const applyOk = applyResp.ok || false;

if (!applyOk && applyResp.error) {
  ctx.plan.warnings = ctx.plan.warnings || [];
  ctx.plan.warnings.push('Failed to apply diff: ' + applyResp.error);
}

return [{ json: { ...ctx, filesChanged, applyOk } }];

